/* MIMORA Competition Demo — standalone, synthetic, frontend-only application. */
const STORE_KEY = 'mimora_competition_demo_v2';
const CHAPTER_STEPS = [
  { title:'Nhận diện tình huống và cảm xúc', short:'Nhận diện cảm xúc', icon:'🌦️', prompt:'Khi tiếng chuông báo ra chơi vang lên, các bạn trong lớp bắt đầu đứng dậy. Con đang cảm thấy thế nào?', choices:[['😊','Vui và háo hức'],['😌','Bình yên'],['😟','Hơi bối rối'],['🤔','Con chưa rõ nữa']] },
  { title:'Bản đồ cơ thể', short:'Bản đồ cơ thể', icon:'🫶', prompt:'Khi có cảm xúc ấy, con nhận thấy điều gì trong cơ thể mình?', choices:[['💗','Tim đập nhanh hơn'],['🌿','Cơ thể khá thoải mái'],['🫧','Bụng hơi cồn cào'],['☁️','Con chưa nhận thấy rõ']] },
  { title:'Thang cường độ', short:'Mức độ cảm xúc', icon:'🎚️', prompt:'Cảm xúc của con lúc này đang ở mức độ nào?', choices:[['🌱','Nhẹ nhàng'],['🌼','Vừa phải'],['🌻','Khá mạnh'],['🌳','Rất mạnh']] },
  { title:'Lựa chọn chiến lược', short:'Chọn điều phù hợp', icon:'🧩', prompt:'Điều gì có thể giúp con cảm thấy dễ chịu hơn lúc này?', choices:[['🌬️','Hít thở chậm một chút'],['🪴','Tìm một góc yên tĩnh'],['🤝','Nhờ người lớn hỗ trợ'],['💬','Nói với bạn điều con cần']] },
  { title:'Sự thật và suy đoán', short:'Sự thật & suy đoán', icon:'🔎', prompt:'Bạn bên cạnh chưa trả lời lời chào của con. Điều nào dưới đây là điều mình biết chắc?', choices:[['👀','Bạn chưa trả lời lời chào'],['💭','Bạn không thích con'],['🌧️','Bạn đang giận con'],['✨','Có thể có nhiều lý do khác nhau']] },
  { title:'Bảng giao tiếp', short:'Nói điều con cần', icon:'💬', prompt:'Con muốn nói điều gì với người bên cạnh?', choices:[['🫶','Con muốn được giúp đỡ'],['⏸️','Con cần nghỉ một chút'],['👂','Con muốn được lắng nghe'],['🌱','Con muốn thử lại']] }
];
function seedState(){
  return {
    role:null,page:'home',studentId:'minhanh',teacherMode:'teacher',selectedChild:'minhanh',selectedBox:'default-minhanh',activeStep:0,
    students:[
      {id:'minhanh',name:'Minh Anh',age:'8 tuổi',avatar:'🌼',school:true,guardian:true,created:false},
      {id:'baoan',name:'Bảo An',age:'7 tuổi',avatar:'🌿',school:false,guardian:true,created:false}
    ],
    boxes:[
      {id:'default-minhanh',type:'default',name:'Box bộ thẻ MIMORA',owner:'MIMORA',studentIds:['minhanh'],description:'Không gian học độc lập theo chương trình chính thức của MIMORA.'},
      {id:'default-baoan',type:'default',name:'Box bộ thẻ MIMORA',owner:'MIMORA',studentIds:['baoan'],description:'Không gian học độc lập theo chương trình chính thức của MIMORA.'},
      {id:'class-1a',type:'class',name:'Lớp Kỹ năng cảm xúc',owner:'Cô Mai',schoolId:'school-1',studentIds:['minhanh'],description:'Lớp học đồng hành cùng trẻ nhận diện cảm xúc và giao tiếp.'},
      {id:'class-1b',type:'class',name:'Lớp Khám phá bản thân',owner:'Cô Lan',schoolId:'school-1',studentIds:[],description:'Không gian học tập theo nhóm nhỏ.'}
    ],
    school:{id:'school-1',name:'Trường MIMORA Demo',code:'SCHOOL-DEMO-01',teachers:[{id:'mai',name:'Cô Mai',role:'Giáo viên lớp',permission:'teacher'},{id:'lan',name:'Cô Lan',role:'Giáo viên lớp',permission:'teacher'},{id:'nam',name:'Thầy Nam',role:'Quản lý trường',permission:'manager'}]},
    content:[
      {id:'c1',type:'emotion_card',title:'Gọi tên cảm xúc',description:'Mỗi cảm xúc đều có điều muốn nói với chúng ta.',status:'published'},
      {id:'c2',type:'situation_card',title:'Tiếng chuông ra chơi',description:'Một tình huống quen thuộc ở trường học.',status:'published'},
      {id:'c3',type:'action_card',title:'Tìm góc yên tĩnh',description:'Một vài cách để con chăm sóc bản thân.',status:'published'},
      {id:'c4',type:'communication_card',title:'Con muốn nói điều gì?',description:'Những cách nhỏ để bày tỏ nhu cầu.',status:'published'},
      {id:'c5',type:'social_story_card',title:'Khi bạn chưa trả lời',description:'Cùng nhìn một tình huống từ nhiều góc độ.',status:'published'},
      {id:'c6',type:'situation_card',title:'Một lời mời cùng chơi',description:'Chờ duyệt nội dung demo trước khi xuất bản.',status:'pending'}
    ],
    progress:{minhanh:{'default-minhanh':2,'class-1a':1},baoan:{'default-baoan':1}},
    answers:{},support:{aac:true,readAloud:true,slowSpeech:true,largeText:false,highContrast:false,reducedMotion:false},
    permissions:{createClass:true,manageRoster:true,assignContent:true,viewProgress:true,delegate:true},
    requests:[{id:'req1',studentId:'baoan',boxId:'class-1a',status:'pending'}],
    activationUsed:false,activatedChildren:[],publishedNew:false,toast:null
  };
}
let state = loadState();
function loadState(){try{const raw=localStorage.getItem(STORE_KEY);if(raw){const parsed=JSON.parse(raw);if(parsed&&parsed.version===2)return parsed.data;}}catch(e){}return seedState();}
function saveState(){try{localStorage.setItem(STORE_KEY,JSON.stringify({version:2,data:state}));}catch(e){}}
const $ = (s,root=document)=>root.querySelector(s);
const main = $('#main');
const modalRoot = $('#modalRoot');
const toastRegion = $('#toastRegion');
const esc = (v='')=>String(v).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const studentById=id=>state.students.find(s=>s.id===id);
const currentStudent=()=>studentById(state.studentId)||state.students[0];
const boxById=id=>state.boxes.find(b=>b.id===id);
const progressFor=(sid,bid)=>Math.max(0,Math.min(6,Number(state.progress?.[sid]?.[bid]||0)));
const percent=(n)=>Math.round(n/6*100);
const typeLabel=t=>({emotion_card:'Thẻ cảm xúc',situation_card:'Thẻ tình huống',action_card:'Thẻ hành động',communication_card:'Thẻ giao tiếp',social_story_card:'Câu chuyện xã hội'}[t]||t);
const boxLabel=t=>({default:'Box mặc định MIMORA',class:'Box lớp học',school:'Box trường học'}[t]||'Box');
function toast(message,type=''){const el=document.createElement('div');el.className='toast '+type;el.textContent=message;toastRegion.appendChild(el);setTimeout(()=>el.remove(),3100);}
function setRole(role){state.role=role;state.page=role==='student'?'student-home':role==='guardian'?'guardian-overview':role==='teacher'?'teacher-overview':'admin-overview';if(role==='student'){state.studentId='minhanh';state.selectedBox='default-minhanh';}saveState();render();}
function goHome(){state.role=null;state.page='home';saveState();render();}
function go(page){state.page=page;saveState();render();}
function initials(s){return s.split(' ').map(x=>x[0]).slice(-2).join('').toUpperCase();}
function avatar(name,color=''){return `<span class="avatar ${color}">${esc(initials(name))}</span>`;}
function stat(label,value,sub,icon){return `<div class="stat-card"><span class="stat-label">${icon||'✦'} &nbsp;${label}</span><div class="stat-value">${value}</div><div class="stat-sub">${sub||''}</div></div>`;}
function progressBar(value){return `<div class="progress-track"><div class="progress-fill" style="width:${Math.max(0,Math.min(100,value))}%"></div></div>`;}
function boxCard(box,studentId,action=true){const n=progressFor(studentId,box.id);const type=box.type;const icon=type==='default'?'🌼':type==='class'?'🌿':'🏡';const tone=type==='default'?'default':type==='class'?'classbox':'schoolbox';return `<article class="box-card ${tone}"><div class="box-symbol">${icon}</div><div class="tag-row"><span class="badge ${type==='default'?'badge-gold':type==='class'?'badge-green':'badge-lav'}">${boxLabel(type)}</span>${type==='default'?'<span class="badge badge-gray">Chính thức</span>':''}</div><h3>${esc(box.name)}</h3><p>${esc(box.description)}</p><div class="progress-label"><span>Tiến trình Chương 1</span><strong>${n}/6 bước</strong></div>${progressBar(percent(n))}<div class="box-meta" style="margin-top:14px"><span class="micro-copy">${type==='default'?'Đơn vị xây dựng: MIMORA':'Phụ trách: '+esc(box.owner)}</span>${action?`<button class="btn btn-small btn-soft" data-action="open-chapter" data-box="${box.id}">Vào học →</button>`:''}</div></article>`;}
function studentBoxes(sid){const s=studentById(sid);return state.boxes.filter(b=>b.type==='default'?b.studentIds.includes(sid):b.type==='class'&&b.studentIds.includes(sid));}
function navConfig(){if(state.role==='student')return [['student-home','⌂','Tổng quan'],['student-boxes','▦','Box học tập'],['student-chapter','✿','Chương 1'],['student-support','♡','Cài đặt hỗ trợ']];if(state.role==='guardian')return [['guardian-overview','⌂','Tổng quan gia đình'],['guardian-activate','▣','Kích hoạt bộ thẻ'],['guardian-children','♧','Tài khoản học sinh'],['guardian-progress','◷','Tiến trình học tập']];if(state.role==='teacher')return [['teacher-overview','⌂','Tổng quan'],['teacher-boxes','▦','Box của tôi'],['teacher-students','♧','Học sinh & thành viên'],['teacher-content','▤','Thư viện nội dung'],['teacher-chapters','✿','Chương học'],['teacher-permissions','⚙','Quyền quản lý']];return [['admin-overview','⌂','Tổng quan'],['admin-content','▤','Thư viện SEL'],['admin-approval','✓','Duyệt nội dung'],['admin-boxes','▦','Hệ thống Box'],['admin-licenses','◇','Giấy phép']];}
function roleMeta(){return ({student:{name:currentStudent().name,sub:'Không gian học tập của con',icon:'🌼',color:''},guardian:{name:'MIMORA Demo Guardian',sub:'Đồng hành cùng con',icon:'♡',color:'terra'},teacher:{name:state.teacherMode==='manager'?'Thầy Nam':'Cô Mai',sub:state.teacherMode==='manager'?'Quản lý trường học':'Giáo viên',icon:'✿',color:''},admin:{name:'MIMORA Platform Team',sub:'Quản trị nền tảng',icon:'✦',color:'lav'}})[state.role];}
function shell(content){const meta=roleMeta();const nav=navConfig();return `<div class="app-layout"><aside class="sidebar"><div class="side-profile">${avatar(meta.name,meta.color)}<div class="profile-meta"><strong>${esc(meta.name)}</strong><span>${esc(meta.sub)}</span></div></div><div class="side-label">Không gian làm việc</div><nav class="nav-list">${nav.map(([page,ico,label])=>`<button class="nav-item ${state.page===page?'active':''}" data-page="${page}"><span class="nav-ico">${ico}</span>${label}</button>`).join('')}</nav><div class="sidebar-bottom"><button class="role-switcher" data-action="switch-role">← Quay lại chọn vai trò</button></div></aside><section class="workspace">${content}</section></div>`;}
function header(title,sub,actions=''){return `<div class="page-header"><div><div class="eyebrow">MIMORA · ${esc(state.role==='student'?'KHÔNG GIAN HỌC TẬP':state.role==='guardian'?'GIA ĐÌNH':state.role==='teacher'?'KHÔNG GIAN GIÁO VIÊN':'NỀN TẢNG')}</div><h2>${title}</h2><p>${sub}</p></div><div class="header-actions">${actions}</div></div>`;}
function homePage(){const roles=[['student','🌼','Học sinh','Khám phá các Box và chương học của con.','#f2efe3','#9a8052'],['guardian','♡','Phụ huynh','Kích hoạt bộ thẻ và đồng hành cùng con.','#f6eae6','#a66f65'],['teacher','✿','Giáo viên','Tổ chức lớp học và tạo các Box học tập.','#e8f0e9','#56806c'],['admin','✦','Quản trị viên','Quản lý nội dung, giấy phép và hệ thống.','#eeecf5','#787291']];return `<div class="welcome"><section class="welcome-hero"><div><div class="eyebrow">Một hành trình học tập nhiều kết nối</div><h1>Cùng con hiểu mình,<br>tự tin lớn lên.</h1><p>MIMORA kết nối bộ thẻ học tập, gia đình và nhà trường trong những không gian học tập ấm áp, nơi mỗi đứa trẻ được tôn trọng theo cách riêng.</p></div><div class="hero-art"><div class="hero-orbit"><div class="hero-kid">🌱</div></div></div></section><section class="role-section"><div class="section-heading"><div><div class="eyebrow">Chào mừng đến với MIMORA</div><h2>Hôm nay bạn muốn khám phá điều gì?</h2></div><p>Chọn một không gian để bắt đầu trải nghiệm.</p></div><div class="role-grid">${roles.map(([r,ico,n,d,bg,fg])=>`<button class="role-card" data-role="${r}"><span class="role-icon" style="background:${bg};color:${fg}">${ico}</span><strong>${n}</strong><small>${d}</small><span class="role-arrow">↗</span></button>`).join('')}</div><div class="home-note">Bản trải nghiệm tương tác · Sử dụng dữ liệu mô phỏng · Chỉ có Chương 1</div></section></div>`;}
function studentHome(){const s=currentStudent();const boxes=studentBoxes(s.id);const defaultBox=boxes.find(b=>b.type==='default');const n=defaultBox?progressFor(s.id,defaultBox.id):0;return `${header(`Chào ${esc(s.name)}! 🌷`,`Hôm nay con muốn khám phá điều gì?`, `<button class="btn btn-outline" data-action="switch-student">Đổi học sinh</button>`)}<div class="content-stack"><div class="panel" style="background:#f0f3e9;border-color:#e3e9db"><div class="row-main"><div class="soft-illustration">☀️</div><div><h3 style="margin:0 0 4px">Mỗi ngày là một khám phá nhỏ</h3><p class="micro-copy" style="margin:0">Con có thể học theo nhịp độ riêng. Không có điểm số hay áp lực phải hoàn thành thật nhanh.</p></div></div></div><div class="stats-grid">${stat('Box đang tham gia',boxes.length,'Những không gian học của con','▦')}${stat('Chương học','01','Chương 1 · Nhận diện bản thân','✿')}${stat('Bước đã khám phá',boxes.reduce((sum,b)=>sum+progressFor(s.id,b.id),0),'Tiến trình được lưu trong bản demo','◷')}${stat('Người đồng hành','1','Phụ huynh của con','♡')}</div><div><div class="panel-head"><div><h3>Những Box của con</h3><p>Con có thể học trong Box mặc định và các Box lớp được mời tham gia.</p></div><button class="btn btn-small btn-outline" data-page="student-boxes">Xem tất cả →</button></div><div class="box-grid">${boxes.map(b=>boxCard(b,s.id)).join('')}</div></div><div class="chapter-card"><div class="chapter-cover"><div class="chapter-art">🌱</div><div><span class="badge badge-gold">Chương trình MIMORA</span><h3 style="margin:7px 0 4px">Chương 1 — Nhận diện cảm xúc và nhu cầu của bản thân</h3><p>Khám phá cảm xúc, lắng nghe cơ thể và tìm cách nói ra điều con cần.</p></div></div><div class="progress-label"><span>Tiến trình trong Box mặc định</span><strong>${n}/6 bước</strong></div>${progressBar(percent(n))}<div style="margin-top:15px"><button class="btn btn-primary" data-action="open-chapter" data-box="${defaultBox?.id||''}">Tiếp tục khám phá →</button></div></div></div>`;}
function studentBoxesPage(){const s=currentStudent();const boxes=studentBoxes(s.id);return `${header('Box học tập của con','Mỗi Box là một không gian học tập. Box mặc định MIMORA luôn ở bên con; Box lớp được thêm khi giáo viên cho phép.',`<button class="btn btn-outline" data-action="switch-student">Đổi học sinh</button>`)}<div class="content-stack"><div class="box-grid">${boxes.map(b=>boxCard(b,s.id)).join('')}</div><div class="panel"><div class="panel-head"><div><h3>Con có lời mời tham gia Box mới</h3><p>Giáo viên có thể mời con tham gia một lớp học. Box sẽ xuất hiện tại đây sau khi được cho phép.</p></div><span class="badge badge-gold">1 lời mời</span></div><div class="notice">🌿 <strong>Lớp Khám phá bản thân</strong> đang chờ giáo viên xác nhận thành viên. Trong bản demo, giáo viên sẽ duyệt lời mời này từ cổng Giáo viên.</div></div></div>`;}
function chapterPage(){const s=currentStudent();const box=boxById(state.selectedBox)||studentBoxes(s.id)[0];if(!box)return `${header('Chương 1','Không tìm thấy Box.')}`;const stepIndex=Math.max(0,Math.min(5,state.activeStep||0));const step=CHAPTER_STEPS[stepIndex];const progress=progressFor(s.id,box.id);return `<div class="learning-wrap">${header('Chương 1 — Nhận diện cảm xúc','Con hãy khám phá từng bước theo cách của riêng mình.',`<button class="btn btn-outline btn-small" data-page="student-boxes">← Các Box</button>`)}<div class="learning-top"><div><span class="badge ${box.type==='default'?'badge-gold':'badge-green'}">${esc(box.name)}</span><div class="micro-copy" style="margin-top:7px">${s.name} · Không cần vội vàng</div></div><span class="badge badge-gray">Bước ${stepIndex+1}/6</span></div><div class="panel" style="margin-bottom:14px"><div class="progress-label"><span>Tiến trình Chương 1</span><strong>${progress}/6 bước</strong></div>${progressBar(percent(progress))}</div><section class="learning-step-card"><div class="learning-step-kicker">Bước ${stepIndex+1} · ${esc(step.title)}</div><h2>${step.icon} ${esc(step.short)}</h2><p class="learning-prompt">${esc(step.prompt)}</p><div class="choice-grid">${step.choices.map(([emoji,label],i)=>`<button class="choice-card" data-action="choose-answer" data-step="${stepIndex}" data-choice="${i}"><span class="choice-emoji">${emoji}</span><span>${label}</span><span style="margin-left:auto;color:#9aab9d">→</span></button>`).join('')}</div><div class="learning-footer"><button class="btn btn-outline" data-action="read-aloud">🔊 Đọc to phần này</button><button class="btn btn-soft" data-action="aac">💬 Con muốn nói</button></div></section><div class="step-list" style="margin-top:15px">${CHAPTER_STEPS.map((st,i)=>`<div class="step-chip ${progressFor(s.id,box.id)>i?'done':''}" style="cursor:pointer" data-action="goto-step" data-step="${i}"><span class="step-num">${progressFor(s.id,box.id)>i?'✓':i+1}</span><span>${st.short}</span></div>`).join('')}</div></div>`;}
function studentSupport(){const pairs=[['aac','Bảng giao tiếp AAC','Giúp con chọn nhanh cách bày tỏ nhu cầu.'],['readAloud','Đọc thành tiếng','Nghe nội dung được đọc chậm rãi.'],['slowSpeech','Tốc độ đọc chậm','Giữ nhịp đọc nhẹ nhàng, dễ theo dõi.'],['largeText','Chữ lớn','Tăng kích thước chữ khi con cần.'],['highContrast','Tương phản cao','Làm nội dung rõ hơn.'],['reducedMotion','Giảm chuyển động','Giảm các hiệu ứng chuyển động.']];return `${header('Cài đặt hỗ trợ','Con có thể chọn những cách hỗ trợ khiến việc học thoải mái hơn.')}<div class="panel"><div class="panel-head"><div><h3>Không gian học phù hợp với con</h3><p>Những lựa chọn này có thể thay đổi bất cứ lúc nào.</p></div><span class="soft-illustration">🫧</span></div>${pairs.map(([key,title,desc])=>`<div class="switch-row"><div><strong style="font-size:11px">${title}</strong><div class="micro-copy">${desc}</div></div><button class="switch ${state.support[key]?'on':''}" data-action="toggle-support" data-key="${key}" aria-label="${title}"></button></div>`).join('')}<div class="notice" style="margin-top:15px">MIMORA tôn trọng lựa chọn của con. Không có cách học nào là đúng duy nhất cho tất cả mọi người.</div></div>`;}
function guardianOverview(){const kids=state.students.filter(s=>s.guardian);return `${header('Không gian gia đình','Một nơi ấm áp để đồng hành cùng hành trình lớn lên của con.',`<button class="btn btn-primary" data-page="guardian-activate">＋ Kích hoạt bộ thẻ</button>`)}<div class="content-stack"><div class="stats-grid">${stat('Tài khoản học sinh',kids.length,'Được liên kết với gia đình','♧')}${stat('Box đang hoạt động',kids.reduce((n,s)=>n+studentBoxes(s.id).length,0),'Box mặc định và Box lớp','▦')}${stat('Chương học','01','Chương 1 đang có trong demo','✿')}${stat('Bộ thẻ đã kích hoạt',state.activationUsed?'2 bộ':'1 bộ','Mã kích hoạt mô phỏng','▣')}</div><div class="panel"><div class="panel-head"><div><h3>Các con trong gia đình</h3><p>Phụ huynh mặc định được liên kết để theo dõi tiến trình học tập.</p></div><button class="btn btn-small btn-outline" data-page="guardian-children">Quản lý tài khoản →</button></div><div class="box-grid">${kids.map(s=>kidCard(s)).join('')}</div></div><div class="panel"><div class="panel-head"><div><h3>Tiến trình gần đây</h3><p>Thông tin mô tả, không xếp hạng và không chấm điểm.</p></div><button class="btn btn-small btn-outline" data-page="guardian-progress">Xem tiến trình →</button></div>${kids.map(s=>`<div class="student-row"><div class="row-main">${avatar(s.name,s.id==='baoan'?'':'terra')}<div><strong>${s.name}</strong><small>${studentBoxes(s.id).length} Box học tập · Chương 1</small></div></div><span class="badge badge-green">Đang khám phá</span></div>`).join('')}</div></div>`;}
function kidCard(s){const boxes=studentBoxes(s.id);const total=boxes.reduce((n,b)=>n+progressFor(s.id,b.id),0);return `<article class="student-card" style="padding:17px"><div class="row-main">${avatar(s.name,s.id==='baoan'?'':'terra')}<div><strong>${s.name}</strong><small>${s.age} · Tài khoản học sinh</small></div></div><div class="tag-row" style="margin:13px 0">${boxes.map(b=>`<span class="badge ${b.type==='default'?'badge-gold':'badge-green'}">${b.type==='default'?'Box mặc định':'Box lớp'}</span>`).join('')}</div><div class="progress-label"><span>Hoạt động đã khám phá</span><strong>${total} bước</strong></div>${progressBar(Math.min(100,total/Math.max(1,boxes.length*6)*100))}<button class="btn btn-small btn-soft" style="margin-top:13px" data-action="guardian-view-child" data-student="${s.id}">Xem tiến trình →</button></article>`;}
function guardianActivate(){return `${header('Kích hoạt bộ thẻ MIMORA','Mỗi bộ thẻ mở ra một không gian học tập riêng dành cho con.')}<div class="two-col"><div class="panel"><div class="soft-illustration">🎁</div><h3>Bộ thẻ học tập MIMORA</h3><p class="micro-copy">Sau khi mua sản phẩm vật lý, phụ huynh sử dụng mã đi kèm để kích hoạt quyền lợi học tập và cấp tài khoản cho con.</p><div class="divider"></div><div class="tag-row"><span class="badge badge-gold">01 tài khoản học sinh</span><span class="badge badge-green">01 Box mặc định</span><span class="badge badge-lav">Phụ huynh liên kết</span></div><div class="notice" style="margin-top:15px">Mã trải nghiệm: <strong>MIMORA-DEMO-2026</strong><br>Đây là mã mô phỏng chỉ dùng trong bản trình diễn.</div></div><div class="panel"><h3>Kích hoạt sản phẩm</h3><p class="micro-copy">Nhập mã được in bên trong hộp thẻ MIMORA.</p>${state.activationUsed?`<div class="notice">✓ Mã demo đã được sử dụng. Tài khoản <strong>An Nhiên</strong> đã được tạo và liên kết với gia đình.</div><button class="btn btn-outline" style="margin-top:13px" data-action="reset-activation">Đặt lại trạng thái kích hoạt</button>`:`<form data-form="activate"><div class="field"><label>Mã kích hoạt sản phẩm</label><input name="code" placeholder="Nhập mã bộ thẻ" autocomplete="off" required /></div><button class="btn btn-primary" type="submit" style="width:100%">Xác nhận kích hoạt →</button></form><p class="hint" style="margin-top:12px">Sau khi kích hoạt thành công, hệ thống sẽ cấp tài khoản học sinh và tự động liên kết với tài khoản phụ huynh hiện tại.</p>`}</div></div>`;}
function guardianChildren(){const kids=state.students.filter(s=>s.guardian);return `${header('Tài khoản học sinh','Quản lý các tài khoản học sinh được liên kết với gia đình.',`<button class="btn btn-primary" data-page="guardian-activate">＋ Kích hoạt bộ thẻ</button>`)}<div class="content-stack"><div class="box-grid">${kids.map(s=>`<article class="panel"><div class="row-main">${avatar(s.name,s.id==='baoan'?'':'terra')}<div><h3 style="margin:0">${s.name}</h3><span class="micro-copy">${s.age} · Đang hoạt động</span></div></div><div class="divider"></div><h4>Các Box đã tham gia</h4>${studentBoxes(s.id).map(b=>`<div class="list-row"><div class="row-main"><span>${b.type==='default'?'🌼':'🌿'}</span><div><strong>${b.name}</strong><small>${boxLabel(b.type)}</small></div></div><span class="badge badge-green">Đang tham gia</span></div>`).join('')}<button class="btn btn-soft btn-small" style="margin-top:12px" data-action="guardian-view-child" data-student="${s.id}">Xem tiến trình</button></article>`).join('')}</div></div>`;}
function guardianProgress(){const selected=studentById(state.selectedChild)||state.students.find(s=>s.guardian);const boxes=studentBoxes(selected.id);return `${header('Tiến trình học tập','Theo dõi hành trình của con qua những thông tin mô tả và tích cực.')}<div class="panel"><div class="panel-head"><div><h3>Chọn học sinh</h3><p>Thông tin tiến trình chỉ hiển thị trong phạm vi tài khoản được liên kết.</p></div></div><div class="student-switch">${state.students.filter(s=>s.guardian).map(s=>`<button class="${selected.id===s.id?'active':''}" data-action="guardian-select-child" data-student="${s.id}">${s.avatar} ${s.name}</button>`).join('')}</div></div><div class="content-stack" style="margin-top:15px"><div class="panel"><div class="row-main">${avatar(selected.name,'terra')}<div><h3 style="margin:0">${selected.name}</h3><p class="micro-copy" style="margin:3px 0 0">Chương 1 — Nhận diện cảm xúc và nhu cầu của bản thân</p></div></div><div class="divider"></div>${boxes.map(b=>{const n=progressFor(selected.id,b.id);return `<div style="padding:10px 0"><div class="row-main" style="justify-content:space-between"><div><strong style="font-size:11px">${b.name}</strong><div class="micro-copy">${boxLabel(b.type)}</div></div><span class="badge ${n>=6?'badge-green':'badge-gold'}">${n>=6?'Đã hoàn thành':'Đang khám phá'}</span></div><div class="progress-label"><span>${n} trên 6 bước đã khám phá</span><strong>${percent(n)}%</strong></div>${progressBar(percent(n))}</div>`;}).join('')}</div><div class="notice">♡ MIMORA chỉ chia sẻ tiến trình tổng quan. Câu trả lời, lựa chọn giao tiếp và ghi chú riêng của giáo viên thuộc không gian riêng tư của trẻ và giáo viên.</div></div>`;}
function teacherModeSwitch(){return `<div class="tabbar"><button class="tab-button ${state.teacherMode==='teacher'?'active':''}" data-action="teacher-mode" data-mode="teacher">Cô Mai · Giáo viên</button><button class="tab-button ${state.teacherMode==='manager'?'active':''}" data-action="teacher-mode" data-mode="manager">Thầy Nam · Quản lý trường</button></div>`;}
function teacherOverview(){const manager=state.teacherMode==='manager';return `${header(manager?'Không gian quản lý trường':'Không gian giáo viên',manager?'Quản lý các Box lớp, giáo viên và quyền trong phạm vi trường học.':'Tổ chức lớp học và đồng hành cùng học sinh trong từng Box.',`<span class="badge ${manager?'badge-lav':'badge-green'}">${manager?'Quyền quản lý trường':'Quyền giáo viên'}</span>`)}${teacherModeSwitch()}<div class="content-stack"><div class="stats-grid">${stat(manager?'Box lớp trong trường':'Box lớp phụ trách',manager?state.boxes.filter(b=>b.type==='class'&&b.schoolId==='school-1').length:state.boxes.filter(b=>b.type==='class'&&b.owner==='Cô Mai').length,'Trong phạm vi được cấp quyền','▦')}${stat('Học sinh',manager?state.students.length:1,'Tài khoản đang liên kết','♧')}${stat('Chương học','01','Chương 1 đang triển khai','✿')}${stat('Thành viên giáo viên',state.school.teachers.length,'Trong Trường MIMORA Demo','♧')}</div>${manager?`<div class="panel"><div class="panel-head"><div><h3>Trường MIMORA Demo</h3><p>Box trường học · Giấy phép mô phỏng đã được cấp.</p></div><span class="badge badge-lav">School Manager</span></div>${schoolTree()}<div style="margin-top:14px"><button class="btn btn-primary" data-action="create-school-class">＋ Tạo Box lớp trong trường</button></div></div>`:`<div class="panel"><div class="panel-head"><div><h3>Box lớp của Cô Mai</h3><p>Giáo viên tạo môi trường học tập riêng cho nhóm học sinh.</p></div><button class="btn btn-primary" data-action="create-class">＋ Tạo Box lớp</button></div><div class="box-grid">${state.boxes.filter(b=>b.type==='class'&&b.owner==='Cô Mai').map(b=>boxCard(b,'minhanh',false)).join('')||'<div class="empty-state">Chưa có Box lớp riêng.</div>'}</div></div>`}<div class="panel"><div class="panel-head"><div><h3>Học sinh gần đây</h3><p>Tiến trình học tập được trình bày theo hướng mô tả.</p></div><button class="btn btn-small btn-outline" data-page="teacher-students">Xem danh sách →</button></div>${state.students.map(s=>`<div class="student-row"><div class="row-main">${avatar(s.name)}<div><strong>${s.name}</strong><small>${s.school?'Có tham gia Box lớp':'Chỉ có Box mặc định'}</small></div></div><span class="badge badge-green">Đang hoạt động</span></div>`).join('')}</div></div>`;}
function schoolTree(){const classes=state.boxes.filter(b=>b.type==='class'&&b.schoolId==='school-1');return `<div class="school-tree"><div class="tree-school"><span>🏫</span><span>${esc(state.school.name)}</span><span class="badge badge-lav">Box trường</span></div><div class="tree-classes">${classes.map(b=>`<div class="tree-class"><span>🌿 ${esc(b.name)}</span><span class="subtle">${b.studentIds.length} học sinh</span></div>`).join('')}</div></div>`;}
function teacherBoxes(){const manager=state.teacherMode==='manager';const own=manager?state.boxes.filter(b=>b.type==='class'&&b.schoolId==='school-1'):state.boxes.filter(b=>b.type==='class'&&b.owner==='Cô Mai');return `${header('Box của tôi','Các không gian học tập được tạo và quản lý theo quyền được cấp.',manager?'<span class="badge badge-lav">Quản lý trường</span>':'<button class="btn btn-primary" data-action="create-class">＋ Tạo Box lớp</button>')}${teacherModeSwitch()}<div class="content-stack"><div class="panel"><div class="panel-head"><div><h3>${manager?'Các Box lớp thuộc trường':'Box lớp do tôi quản lý'}</h3><p>${manager?'Quản lý nhiều Box lớp trong một Box trường.':'Mỗi Box lớp là một nhóm học sinh có lộ trình học tập riêng.'}</p></div></div><div class="box-grid">${own.map(b=>`<div class="box-card classbox"><div class="box-symbol">🌿</div><span class="badge badge-green">Box lớp</span><h3>${esc(b.name)}</h3><p>${esc(b.description)}</p><div class="box-meta"><span class="micro-copy">${b.studentIds.length} học sinh</span><button class="btn btn-small btn-soft" data-action="manage-box" data-box="${b.id}">Quản lý →</button></div></div>`).join('')}</div></div>${manager?`<div class="panel"><div class="panel-head"><div><h3>Cấu trúc Box trường</h3><p>Trường học có thể chứa nhiều Box lớp.</p></div></div>${schoolTree()}</div>`:''}</div>`;}
function teacherStudents(){const manager=state.teacherMode==='manager';const visibleStudents=state.students.filter(s=>state.boxes.some(b=>b.type==='class'&&(manager?b.schoolId==='school-1':b.owner==='Cô Mai')&&b.studentIds.includes(s.id)));const visibleRequests=state.requests.filter(r=>r.status==='pending'&&(()=>{const b=boxById(r.boxId);return b&&(manager?b.schoolId==='school-1':b.owner==='Cô Mai');})());return `${header('Học sinh & thành viên','Quản lý học sinh trong phạm vi Box được phân công.')} ${teacherModeSwitch()}<div class="content-stack"><div class="panel"><div class="panel-head"><div><h3>Danh sách học sinh</h3><p>Giáo viên chỉ xem và quản lý học sinh thuộc Box được cấp quyền.</p></div><button class="btn btn-small btn-outline" data-action="invite-student">＋ Mời học sinh</button></div>${visibleStudents.map(s=>`<div class="student-row"><div class="row-main">${avatar(s.name)}<div><strong>${s.name}</strong><small>${s.school?'Lớp Kỹ năng cảm xúc · Minh Anh':'Box mặc định MIMORA · Bảo An'}</small></div></div><div class="row-actions"><span class="badge ${s.school?'badge-green':'badge-gold'}">${s.school?'Đã tham gia':'Chưa tham gia Box lớp'}</span><button class="btn btn-small btn-outline" data-action="view-student-support" data-student="${s.id}">Hồ sơ hỗ trợ</button></div></div>`).join('')}</div><div class="panel"><div class="panel-head"><div><h3>Yêu cầu tham gia Box lớp</h3><p>Học sinh chỉ xuất hiện trong Box sau khi giáo viên cho phép.</p></div><span class="badge badge-gold">${visibleRequests.length} chờ xử lý</span></div>${visibleRequests.map(r=>{const s=studentById(r.studentId),b=boxById(r.boxId);return `<div class="student-row"><div class="row-main">${avatar(s.name)}<div><strong>${s.name}</strong><small>Muốn tham gia ${b.name}</small></div></div><div class="row-actions"><button class="btn btn-small btn-primary" data-action="approve-request" data-request="${r.id}">Cho phép</button><button class="btn btn-small btn-outline" data-action="decline-request" data-request="${r.id}">Từ chối</button></div></div>`;}).join('')||'<div class="empty-state"><div class="big">🌱</div><p>Không có yêu cầu đang chờ.</p></div>'}</div></div>`;}
function teacherContent(){return `${header('Thư viện nội dung MIMORA','Nội dung chính thức do MIMORA xây dựng và phê duyệt.')}<div class="panel"><div class="panel-head"><div><h3>Học liệu đã xuất bản</h3><p>Giáo viên lựa chọn nội dung phù hợp để tổ chức Chương 1.</p></div><span class="badge badge-green">${state.content.filter(c=>c.status==='published').length} nội dung</span></div>${state.content.filter(c=>c.status==='published').map(c=>`<div class="list-row"><div class="row-main"><span class="box-symbol" style="width:34px;height:34px;margin:0">${contentIcon(c.type)}</span><div><strong>${esc(c.title)}</strong><small>${typeLabel(c.type)} · ${esc(c.description)}</small></div></div><span class="badge badge-green">Đã xuất bản</span></div>`).join('')}</div>`;}
function teacherChapters(){return `${header('Chương học','Tổ chức lộ trình học trong Box lớp. Demo hiện chỉ triển khai Chương 1.')}<div class="content-stack"><div class="chapter-card"><div class="chapter-cover"><div class="chapter-art">🌱</div><div><span class="badge badge-gold">Chương trình chính thức MIMORA</span><h3 style="margin:7px 0 4px">Chương 1 — Nhận diện cảm xúc và nhu cầu của bản thân</h3><p>Sáu bước khám phá được sắp xếp trong cùng một chương học.</p></div></div><div class="step-list">${CHAPTER_STEPS.map((s,i)=>`<div class="step-chip"><span class="step-num">${i+1}</span><span>${s.short}</span></div>`).join('')}</div></div><div class="notice">Giáo viên có thể tổ chức hoạt động của Chương 1 trong Box lớp. Nội dung chính thức của Box mặc định vẫn do MIMORA quản lý.</div></div>`;}
function teacherPermissions(){const manager=state.teacherMode==='manager';const permissions=manager?[['createClass','Tạo và quản lý Box lớp','Tạo Box lớp trong trường'],['manageRoster','Quản lý học sinh','Thêm, xóa và duyệt thành viên'],['assignContent','Tổ chức chương học','Phân công nội dung học tập'],['viewProgress','Theo dõi tiến trình','Xem trạng thái học tập mô tả'],['delegate','Phân quyền giáo viên','Cấp quyền trong phạm vi Box trường']]:[['createClass','Tạo Box lớp','Tạo lớp học theo giấy phép'],['manageRoster','Quản lý danh sách học sinh','Thêm hoặc xóa học sinh trong Box'],['assignContent','Tổ chức chương học','Lựa chọn và phân công học liệu'],['viewProgress','Theo dõi tiến trình','Xem tiến trình của học sinh trong Box'],['delegate','Ủy quyền','Chuyển giao một số quyền được phép']];return `${header('Quyền quản lý','Mỗi giáo viên chỉ thực hiện thao tác trong phạm vi Box và giấy phép được cấp.')}${teacherModeSwitch()}<div class="content-stack"><div class="panel"><div class="panel-head"><div><h3>${manager?'Quyền quản lý trường của Thầy Nam':'Quyền của Cô Mai'}</h3><p>${manager?'Quản lý trường học có quyền quản lý Box lớp và thành viên giáo viên.':'Các quyền quản lý lớp được MIMORA cấp cho tài khoản giáo viên.'}</p></div><span class="badge ${manager?'badge-lav':'badge-green'}">${manager?'School Manager':'Teacher'}</span></div><div class="permission-grid">${permissions.map(([key,title,desc])=>`<div class="permission-item"><div class="switch-row" style="padding:0;border:0"><div><strong>${title}</strong><small>${desc}</small></div><button class="switch ${state.permissions[key]?'on':''}" data-action="toggle-permission" data-key="${key}"></button></div></div>`).join('')}</div></div><div class="panel"><div class="panel-head"><div><h3>Giáo viên trong phạm vi trường</h3><p>Thầy Nam có thể phân công quyền quản lý trong Trường MIMORA Demo.</p></div><button class="btn btn-small btn-outline" data-action="add-teacher">＋ Thêm giáo viên</button></div>${state.school.teachers.map(t=>`<div class="member-row"><div class="row-main">${avatar(t.name)}<div><strong>${t.name}</strong><small>${t.role}</small></div></div><span class="badge ${t.permission==='manager'?'badge-lav':'badge-green'}">${t.permission==='manager'?'Quản lý trường':'Giáo viên'}</span></div>`).join('')}</div><div class="notice lav">Quyền quản lý trường không tạo ra vai trò đăng nhập thứ năm. Người quản lý trường vẫn sử dụng cổng Giáo viên, với quyền hạn được mở rộng theo giấy phép.</div></div>`;}
function adminOverview(){return `${header('Tổng quan nền tảng','MIMORA quản lý nội dung chính thức, Box và giấy phép trong hệ sinh thái học tập.')}<div class="content-stack"><div class="stats-grid">${stat('Tài khoản học sinh',state.students.length,'Dữ liệu mô phỏng','♧')}${stat('Box đang hoạt động',state.boxes.length,'Bao gồm Box mặc định và Box lớp','▦')}${stat('Nội dung đã xuất bản',state.content.filter(c=>c.status==='published').length,'Thư viện SEL chính thức','▤')}${stat('Giấy phép trường',1,'Trường MIMORA Demo','◇')}</div><div class="two-col"><div class="panel"><div class="panel-head"><div><h3>Quản lý nội dung</h3><p>Đảm bảo chất lượng học liệu MIMORA.</p></div><button class="btn btn-small btn-outline" data-page="admin-approval">Hàng đợi →</button></div><div class="row-main"><div class="chapter-art" style="width:48px;height:48px;font-size:22px">📚</div><div><strong>${state.content.filter(c=>c.status==='published').length} học liệu đang xuất bản</strong><small>${state.content.filter(c=>c.status==='pending').length} nội dung chờ duyệt</small></div></div></div><div class="panel"><div class="panel-head"><div><h3>Hệ thống Box</h3><p>Các không gian thuộc hệ sinh thái.</p></div><button class="btn btn-small btn-outline" data-page="admin-boxes">Xem →</button></div><div class="row-main"><div class="chapter-art" style="width:48px;height:48px;font-size:22px">▦</div><div><strong>${state.boxes.length} Box đang hoạt động</strong><small>1 Box trường · ${state.boxes.filter(b=>b.type==='class').length} Box lớp · ${state.boxes.filter(b=>b.type==='default').length} Box mặc định</small></div></div></div></div><div class="notice lav">Quản trị viên quản lý chất lượng nội dung, giấy phép và vận hành hệ thống. Không truy cập câu trả lời riêng tư hoặc lượt tương tác chi tiết của từng học sinh.</div></div>`;}
function contentIcon(t){return ({emotion_card:'♡',situation_card:'☁',action_card:'✿',communication_card:'💬',social_story_card:'📖'}[t]||'✦');}
function adminContent(){return `${header('Thư viện SEL','Quản lý nội dung học tập chính thức của MIMORA.')}<div class="panel"><div class="panel-head"><div><h3>Học liệu SEL</h3><p>Năm nhóm nội dung chuẩn hóa.</p></div><button class="btn btn-small btn-outline" data-action="new-content">＋ Tạo nội dung</button></div>${state.content.map(c=>`<div class="list-row"><div class="row-main"><span class="box-symbol" style="width:35px;height:35px;margin:0">${contentIcon(c.type)}</span><div><strong>${esc(c.title)}</strong><small>${typeLabel(c.type)} · ${esc(c.description)}</small></div></div><span class="badge ${c.status==='published'?'badge-green':'badge-gold'}">${c.status==='published'?'Đã xuất bản':'Chờ duyệt'}</span></div>`).join('')}</div>`;}
function adminApproval(){const pending=state.content.filter(c=>c.status==='pending');return `${header('Hàng đợi phê duyệt','Rà soát nội dung trước khi đưa vào thư viện chính thức.')}<div class="content-stack">${pending.map(c=>`<div class="panel"><div class="panel-head"><div><span class="badge badge-gold">Chờ duyệt</span><h3 style="margin:9px 0 4px">${esc(c.title)}</h3><p>${typeLabel(c.type)}</p></div><span class="soft-illustration">📝</span></div><p class="micro-copy">${esc(c.description)}</p><div class="notice">Nội dung sau khi xuất bản sẽ xuất hiện trong thư viện của giáo viên và có thể được tổ chức trong Box lớp.</div><div class="modal-actions"><button class="btn btn-outline" data-action="review-content" data-id="${c.id}">Xem trước</button><button class="btn btn-primary" data-action="publish-content" data-id="${c.id}">Phê duyệt & xuất bản</button></div></div>`).join('')||'<div class="panel empty-state"><div class="big">🌿</div><h3>Hàng đợi đã trống</h3><p>Không có nội dung đang chờ phê duyệt.</p></div>'}</div>`;}
function adminBoxes(){return `${header('Hệ thống Box','Theo dõi cấu trúc Box mặc định, Box lớp và Box trường.')}<div class="content-stack"><div class="panel"><div class="panel-head"><div><h3>Cấu trúc trường học</h3><p>Box trường là đơn vị tổ chức chứa nhiều Box lớp.</p></div><span class="badge badge-lav">Đã cấp phép</span></div>${schoolTree()}</div><div class="box-grid">${state.boxes.map(b=>boxCard(b,b.studentIds[0]||'minhanh',false)).join('')}</div></div>`;}
function adminLicenses(){return `${header('Giấy phép & đối tác','Quản lý quyền tạo Box theo gói cấp phép của MIMORA.')}<div class="content-stack"><div class="panel"><div class="panel-head"><div><h3>Giấy phép trường học</h3><p>Trường MIMORA Demo · Mã giấy phép MIMORA-SCHOOL-DEMO</p></div><span class="badge badge-green">Đang hiệu lực</span></div><div class="stats-grid">${stat('Box trường','01','Được cấp phép','🏫')}${stat('Box lớp','02','Trong trường','▦')}${stat('Giáo viên','03','Thành viên','♧')}${stat('Trạng thái','Tốt','Mô phỏng cuộc thi','✓')}</div></div><div class="panel"><div class="panel-head"><div><h3>Quyền tạo Box lớp</h3><p>Cô Mai được cấp quyền tạo Box lớp theo giấy phép mô phỏng.</p></div><span class="badge badge-green">Được cấp</span></div><div class="notice">Giáo viên có thể tạo Box lớp khi tài khoản được MIMORA cấp quyền tương ứng. Việc tạo Box trường yêu cầu giấy phép trường học riêng.</div></div></div>`;}
function render(){const topSwitch=$('#switchRole');topSwitch.classList.toggle('hidden',!state.role);if(!state.role){main.innerHTML=homePage();return;}let content='';if(state.role==='student'){content=({ 'student-home':studentHome,'student-boxes':studentBoxesPage,'student-chapter':chapterPage,'student-support':studentSupport }[state.page]||studentHome)();}else if(state.role==='guardian'){content=({ 'guardian-overview':guardianOverview,'guardian-activate':guardianActivate,'guardian-children':guardianChildren,'guardian-progress':guardianProgress }[state.page]||guardianOverview)();}else if(state.role==='teacher'){content=({ 'teacher-overview':teacherOverview,'teacher-boxes':teacherBoxes,'teacher-students':teacherStudents,'teacher-content':teacherContent,'teacher-chapters':teacherChapters,'teacher-permissions':teacherPermissions }[state.page]||teacherOverview)();}else{content=({ 'admin-overview':adminOverview,'admin-content':adminContent,'admin-approval':adminApproval,'admin-boxes':adminBoxes,'admin-licenses':adminLicenses }[state.page]||adminOverview)();}main.innerHTML=shell(content);}
function openModal(title,body,foot=''){modalRoot.innerHTML=`<div class="modal-backdrop" data-action="backdrop-close"><div class="modal" role="dialog" aria-modal="true"><div class="modal-head"><h3>${title}</h3><button class="modal-close" data-action="close-modal">✕</button></div>${body}${foot?`<div class="modal-actions">${foot}</div>`:''}</div></div>`;}
function closeModal(){modalRoot.innerHTML='';}
function createBoxModal(school=false){openModal(school?'Tạo Box lớp trong trường':'Tạo Box lớp mới',`<form data-form="create-box"><div class="field"><label>Tên Box lớp</label><input name="name" placeholder="Ví dụ: Lớp Kỹ năng giao tiếp" required maxlength="60"></div><div class="field"><label>Mô tả</label><textarea name="description" rows="3" placeholder="Mục tiêu và cách tổ chức lớp học"></textarea></div><div class="notice">Box lớp mới sẽ có Chương 1. Học sinh chỉ tham gia sau khi giáo viên cho phép.</div><input type="hidden" name="school" value="${school?'yes':'no'}"></form>`,`<button class="btn btn-outline" data-action="close-modal">Hủy</button><button class="btn btn-primary" data-action="submit-create-box">Tạo Box</button>`);}
function showStudentChooser(){openModal('Chọn tài khoản học sinh',`<div class="student-switch">${state.students.map(s=>`<button data-action="choose-student" data-student="${s.id}">${s.avatar} ${s.name}</button>`).join('')}</div><p class="micro-copy" style="margin-top:14px">Hai hồ sơ chỉ dùng để trình diễn hai bối cảnh học tập khác nhau. Mỗi hồ sơ là một tài khoản học sinh riêng.</p>`);}
function handleAction(el){const a=el.dataset.action;switch(a){case 'switch-role':goHome();break;case 'open-chapter':state.selectedBox=el.dataset.box;state.activeStep=0;go('student-chapter');break;case 'switch-student':showStudentChooser();break;case 'choose-student':state.studentId=el.dataset.student;state.selectedBox=studentBoxes(state.studentId)[0]?.id||'';closeModal();go('student-home');break;case 'choose-answer':{const idx=Number(el.dataset.step),choice=Number(el.dataset.choice),s=currentStudent(),bid=state.selectedBox;state.answers[`${s.id}:${bid}:${idx}`]=choice;const now=progressFor(s.id,bid);if(now<idx+1){state.progress[s.id]=state.progress[s.id]||{};state.progress[s.id][bid]=Math.min(6,Math.max(now,idx+1));}state.activeStep=Math.min(5,idx+1);saveState();render();toast(idx===5?'Con đã khám phá đủ sáu bước của Chương 1.':'Lựa chọn của con đã được lưu trong bản demo.');break;}case 'goto-step':state.activeStep=Number(el.dataset.step);saveState();render();break;case 'read-aloud':{const text=CHAPTER_STEPS[state.activeStep].prompt;if('speechSynthesis'in window){window.speechSynthesis.cancel();const u=new SpeechSynthesisUtterance(text);u.lang='vi-VN';u.rate=state.support.slowSpeech?.82:1;window.speechSynthesis.speak(u);toast('MIMORA đang đọc nội dung cho con nghe.');}else toast('Trình duyệt này chưa hỗ trợ đọc thành tiếng.');break;}case 'aac':openModal('Con muốn nói điều gì?','<div class="choice-grid"><button class="choice-card" data-action="aac-say" data-text="Con cần nghỉ một chút.">⏸️ Con cần nghỉ một chút</button><button class="choice-card" data-action="aac-say" data-text="Con muốn được giúp đỡ.">🤝 Con muốn được giúp đỡ</button><button class="choice-card" data-action="aac-say" data-text="Con muốn được lắng nghe.">💬 Con muốn được lắng nghe</button><button class="choice-card" data-action="aac-say" data-text="Con muốn thử lại.">🌱 Con muốn thử lại</button></div>');break;case 'aac-say':closeModal();toast(el.dataset.text);break;case 'toggle-support':state.support[el.dataset.key]=!state.support[el.dataset.key];saveState();render();toast('Đã cập nhật cách hỗ trợ của con.');break;case 'guardian-view-child':state.selectedChild=el.dataset.student;go('guardian-progress');break;case 'guardian-select-child':state.selectedChild=el.dataset.student;saveState();render();break;case 'reset-activation':state.activationUsed=false;state.students=state.students.filter(s=>s.id!=='annhien');state.boxes=state.boxes.filter(b=>b.id!=='default-annhien');delete state.progress.annhien;saveState();render();toast('Đã đặt lại mã kích hoạt mô phỏng.');break;case 'teacher-mode':state.teacherMode=el.dataset.mode;saveState();render();toast(state.teacherMode==='manager'?'Đang xem với quyền Quản lý trường.':'Đang xem với quyền Giáo viên.');break;case 'create-class':createBoxModal(false);break;case 'create-school-class':createBoxModal(true);break;case 'approve-request':{const r=state.requests.find(x=>x.id===el.dataset.request);if(r){r.status='approved';const b=boxById(r.boxId),s=studentById(r.studentId);if(b&&!b.studentIds.includes(s.id))b.studentIds.push(s.id);s.school=true;state.progress[s.id]=state.progress[s.id]||{};state.progress[s.id][b.id]=0;saveState();render();toast(`${s.name} đã được cho phép tham gia ${b.name}.`);}break;}case 'decline-request':{const r=state.requests.find(x=>x.id===el.dataset.request);if(r)r.status='declined';saveState();render();toast('Đã từ chối yêu cầu tham gia.');break;}case 'manage-box':openModal('Quản lý Box lớp',`<h3>${esc(boxById(el.dataset.box)?.name||'Box lớp')}</h3><p class="micro-copy">Chương trình học đang sử dụng: Chương 1 — Nhận diện cảm xúc và nhu cầu của bản thân.</p><div class="notice">Thành viên và tiến trình được quản lý trong phạm vi Box này. Học sinh vẫn giữ Box mặc định MIMORA.</div>`);break;case 'view-student-support':{const s=studentById(el.dataset.student);openModal(`Hồ sơ hỗ trợ · ${s.name}`,`<div class="tag-row"><span class="badge badge-green">AAC bật</span><span class="badge badge-green">Đọc thành tiếng</span><span class="badge badge-gold">Tốc độ chậm</span></div><p class="micro-copy" style="margin-top:14px">Mục tiêu: nhận diện cảm xúc và lựa chọn cách diễn đạt nhu cầu. Hồ sơ minh họa chỉ là dữ liệu mô phỏng.</p>`);break;}case 'invite-student':openModal('Mời học sinh tham gia Box','<p class="micro-copy">Chọn học sinh hiện có. Giáo viên sẽ gửi lời mời tham gia Box lớp; danh tính học sinh không bị tạo trùng.</p><div class="student-switch"><button data-action="make-request" data-student="baoan">🌿 Bảo An</button><button data-action="make-request" data-student="minhanh">🌼 Minh Anh</button></div>');break;case 'make-request':{const sid=el.dataset.student;if(!state.requests.some(r=>r.studentId===sid&&r.boxId==='class-1a'&&r.status==='pending'))state.requests.push({id:'req'+Date.now(),studentId:sid,boxId:'class-1a',status:'pending'});closeModal();go('teacher-students');toast('Đã tạo yêu cầu tham gia Box lớp.');break;}case 'toggle-permission':state.permissions[el.dataset.key]=!state.permissions[el.dataset.key];saveState();render();toast('Quyền trong bản demo đã được cập nhật.');break;case 'add-teacher':openModal('Thêm giáo viên vào Box trường','<form data-form="add-teacher"><div class="field"><label>Tên giáo viên</label><input name="name" placeholder="Ví dụ: Cô Hương" required></div><div class="field"><label>Phân quyền</label><select name="permission"><option value="teacher">Giáo viên lớp</option><option value="manager">Quản lý trường</option></select></div></form>','<button class="btn btn-outline" data-action="close-modal">Hủy</button><button class="btn btn-primary" data-action="submit-add-teacher">Thêm thành viên</button>');break;case 'publish-content':{const c=state.content.find(x=>x.id===el.dataset.id);if(c){c.status='published';state.publishedNew=true;saveState();render();toast('Nội dung đã được phê duyệt và xuất bản. Thư viện giáo viên đã cập nhật.');}break;}case 'review-content':{const c=state.content.find(x=>x.id===el.dataset.id);openModal('Xem trước nội dung',`<span class="badge badge-gold">${typeLabel(c.type)}</span><h3 style="margin-top:12px">${esc(c.title)}</h3><p class="micro-copy">${esc(c.description)}</p><div class="notice">Nội dung mô phỏng dành cho chương trình học Chương 1.</div>`);break;}case 'new-content':openModal('Tạo nội dung SEL','<form data-form="new-content"><div class="field"><label>Tên nội dung</label><input name="title" required placeholder="Tên học liệu"></div><div class="field"><label>Nhóm nội dung</label><select name="type"><option value="emotion_card">Thẻ cảm xúc</option><option value="situation_card">Thẻ tình huống</option><option value="action_card">Thẻ hành động</option><option value="communication_card">Thẻ giao tiếp</option><option value="social_story_card">Câu chuyện xã hội</option></select></div><div class="field"><label>Mô tả</label><textarea name="description" rows="2"></textarea></div></form>','<button class="btn btn-outline" data-action="close-modal">Hủy</button><button class="btn btn-primary" data-action="submit-new-content">Lưu bản nháp</button>');break;case 'reset-demo':resetDemo();break;case 'close-modal':closeModal();break;case 'backdrop-close':break;case 'submit-create-box':submitModalForm('create-box');break;case 'submit-add-teacher':submitModalForm('add-teacher');break;case 'submit-new-content':submitModalForm('new-content');break;}}
function submitModalForm(name){const form=$(`form[data-form="${name}"]`);if(!form)return;if(!form.reportValidity())return;const fd=new FormData(form);if(name==='create-box'){const boxName=String(fd.get('name')).trim();if(!boxName)return;const isSchool=fd.get('school')==='yes';const id='class-'+Date.now();state.boxes.push({id,type:'class',name:boxName,owner:state.teacherMode==='manager'?'Thầy Nam':'Cô Mai',schoolId:isSchool||state.teacherMode==='manager'?'school-1':null,studentIds:[],description:String(fd.get('description')||'Box lớp học mới được tạo trong bản demo.')});closeModal();saveState();render();toast('Box lớp mới đã được tạo. Chương 1 đã sẵn sàng.');}else if(name==='add-teacher'){const n=String(fd.get('name')).trim();const p=String(fd.get('permission'));state.school.teachers.push({id:'t'+Date.now(),name:n,role:p==='manager'?'Quản lý trường':'Giáo viên lớp',permission:p});closeModal();saveState();render();toast('Đã thêm giáo viên vào Box trường.');}else if(name==='new-content'){state.content.push({id:'c'+Date.now(),type:String(fd.get('type')),title:String(fd.get('title')),description:String(fd.get('description')||''),status:'pending'});closeModal();saveState();render();toast('Đã lưu nội dung vào hàng đợi phê duyệt.');}}
function resetDemo(){if(!confirm('Đặt lại toàn bộ tiến trình mô phỏng về trạng thái ban đầu?'))return;state=seedState();saveState();closeModal();render();toast('Đã đặt lại kịch bản demo ban đầu.');}
main.addEventListener('click',e=>{const role=e.target.closest('[data-role]');if(role){setRole(role.dataset.role);return;}const nav=e.target.closest('[data-page]');if(nav){go(nav.dataset.page);return;}const action=e.target.closest('[data-action]');if(action){handleAction(action);return;}});
modalRoot.addEventListener('click',e=>{if(e.target.classList && e.target.classList.contains('modal-backdrop')){closeModal();return;}const a=e.target.closest('[data-action]');if(a)handleAction(a);});
document.addEventListener('submit',e=>{const form=e.target.closest('form[data-form]');if(!form)return;e.preventDefault();const type=form.dataset.form;if(type==='create-box'||type==='add-teacher'||type==='new-content'){submitModalForm(type);return;}if(type==='activate'){const code=String(new FormData(form).get('code')||'').trim().toUpperCase();if(code!=='MIMORA-DEMO-2026'){toast('Mã kích hoạt chưa đúng. Hãy thử MIMORA-DEMO-2026.','error');return;}if(state.activationUsed){toast('Mã demo này đã được sử dụng.','error');return;}state.activationUsed=true;state.students.push({id:'annhien',name:'An Nhiên',age:'8 tuổi',avatar:'🌷',school:false,guardian:true,created:true});state.boxes.push({id:'default-annhien',type:'default',name:'Box bộ thẻ MIMORA',owner:'MIMORA',studentIds:['annhien'],description:'Không gian học độc lập theo chương trình chính thức của MIMORA.'});state.progress.annhien={'default-annhien':0};saveState();render();openModal('Kích hoạt thành công 🌼',`<div class="notice">Bộ thẻ MIMORA đã được kích hoạt. Tài khoản học sinh đã được cấp và tự động liên kết với phụ huynh.</div><div class="panel" style="margin-top:13px;background:#f0f3e9"><div class="row-main">${avatar('An Nhiên','terra')}<div><strong>An Nhiên</strong><small>Tài khoản học sinh mới</small></div></div><div class="divider"></div><div class="tag-row"><span class="badge badge-gold">Box mặc định MIMORA</span><span class="badge badge-green">Phụ huynh đã liên kết</span></div></div><p class="micro-copy" style="margin-top:12px">Trong hệ thống thực tế, thông tin đăng nhập sẽ được bàn giao an toàn cho phụ huynh theo quy trình cấp phát tài khoản.</p>`,'<button class="btn btn-primary" data-action="close-modal">Hoàn tất</button>');}});
$('#brandHome').addEventListener('click',goHome);$('#switchRole').addEventListener('click',goHome);$('#resetDemo').addEventListener('click',resetDemo);
render();
